package com.mob.lee.fastair.bench

import com.zevarc.zevhub.session.Session
import com.zevarc.zevhub.transfer.TransferDestination
import com.zevarc.zevhub.transfer.TransferMetadata
import com.zevarc.zevhub.transfer.TransferResult
import com.zevarc.zevhub.transfer.TransferSource
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.async
import kotlinx.coroutines.launch
import kotlinx.coroutines.withTimeoutOrNull

/**
 * A synthetic throughput measurement over the real session.
 *
 * Sends generated bytes through the same transfer path a file takes — same
 * framing, same chunking, same backpressure — into a sink that discards. That
 * isolates the transport from storage and from the file picker, so the number
 * is comparable between builds and between devices.
 *
 * Chunk size is a parameter because it trades per-frame overhead against
 * syscalls, and which side dominates depends on the link.
 */
object TransferBench {

    /** Payload marker so bench traffic never collides with real files. */
    const val TYPE = "fastair/bench"

    private const val MAX_WAIT_MS = 20_000L

    private const val TAG = "Bench"

    /** One completed measurement. */
    data class Report(
        val requestedBytes: Long,
        val receivedBytes: Long,
        val millis: Long,
        val chunk: Int,
        val cancelled: Boolean = false
    ) {
        val mbPerSecond: Double
            get() = if (millis <= 0) 0.0 else requestedBytes.toDouble() / 1024 / 1024 / (millis / 1000.0)

        val mbitPerSecond: Double get() = mbPerSecond * 8

        val complete: Boolean get() = !cancelled && receivedBytes == requestedBytes
    }

    /** Generates [length] bytes without touching disk. */
    private class GeneratedSource(
        private val length: Long,
        chunk: Int
    ) : TransferSource {
        override val totalBytes: Long = length
        override val metadata = TransferMetadata(TYPE, ByteArray(0))
        private var sent = 0L
        private val pattern = ByteArray(minOf(chunk, 64 * 1024)) { (it % 251).toByte() }

        override suspend fun read(maxBytes: Int): ByteArray? {
            val room = length - sent
            if (room <= 0) return null
            val size = minOf(pattern.size.toLong(), room).toInt()
            sent += size
            // A fresh array every time: the wire must never alias the pattern.
            return pattern.copyOf(size)
        }
    }

    /** Counts bytes; correctness is covered by the unit tests, not here. */
    private class CountingSink : TransferDestination {
        var bytes = 0L
        override suspend fun write(data: ByteArray) {
            bytes += data.size
        }
        override suspend fun close() {}
    }

    /**
     * Sends [bytes] and reports the achieved rate.
     *
     * The receiver must be this same app, since the other side has to accept the
     * offer before data flows.
     */
    suspend fun run(
        scope: CoroutineScope,
        session: Session,
        bytes: Long,
        chunk: Int,
        onSent: (sent: Long) -> Unit = {}
    ): Report {
        val started = System.nanoTime()
        val transfer = session.transfer(GeneratedSource(bytes, chunk))

        val watcher: Job = scope.launch {
            runCatching { transfer.progress.collect { onSent(it.bytesTransferred) } }
        }

        val result: TransferResult? = withTimeoutOrNull(MAX_WAIT_MS) { transfer.await() }

        watcher.cancel()
        val elapsed = (System.nanoTime() - started) / 1_000_000

        return if (result == null) {
            transfer.cancel()
            Report(bytes, 0, elapsed, chunk, cancelled = true)
        } else {
            Report(bytes, bytes, elapsed, chunk)
        }
    }
}

/** Reports what the sending side moved; the peer counts its own side. */
